const pages = $input.all().map(item => item.json);
const graphInboxUrl = RegExp("^https://mail[.]secdash[.]invalid(?::443)?/v1[.]0/me/mailFolders(?:/inbox|[(]'inbox'[)]|%28%27inbox%27%29)/messages(?:[?]|$)", "i");
const outlookMessageUrl = RegExp("^https://inbox[.]secdash[.]invalid(?::443)?(?:/|$)", "i");
const seen = new Set();
const output = [];
function checkedNextLink(raw) {
  if (raw === undefined || raw === null || raw === '') return null;
  if (typeof raw !== 'string') throw new Error('Microsoft Graph pagination URL is not a string');
  if (!graphInboxUrl.test(raw)) throw new Error('Microsoft Graph returned an unexpected pagination URL');
  return raw;
}
for (const page of pages) {
  if (!page || !Array.isArray(page.value)) throw new Error('Microsoft Graph returned an invalid message page');
  checkedNextLink(page['@odata.nextLink']);
  for (const message of page.value) {
    const providerId = typeof message?.internetMessageId === 'string' && message.internetMessageId.trim() ? message.internetMessageId.trim() : (typeof message?.id === 'string' ? message.id.trim() : '');
    if (!providerId) throw new Error('Inbox message is missing both internetMessageId and Graph id');
    if (providerId.length > 1000) throw new Error('Inbox message identifier exceeds the dashboard limit');
    if (seen.has(providerId)) continue;
    seen.add(providerId);
    const sender = typeof message?.from?.emailAddress?.address === 'string' && message.from.emailAddress.address.trim() ? message.from.emailAddress.address.trim() : (typeof message?.from?.emailAddress?.name === 'string' ? message.from.emailAddress.name.trim() : '');
    if (!sender) throw new Error('Inbox message is missing its sender');
    if (sender.length > 500) throw new Error('Inbox message sender exceeds the dashboard limit');
    const subject = message?.subject == null ? '' : String(message.subject);
    if (subject.length > 1000) throw new Error('Inbox message subject exceeds the dashboard limit');
    if (message?.body?.contentType?.toLowerCase() !== 'text' || typeof message?.body?.content !== 'string') throw new Error('Inbox message body was not returned as plain text');
    const body = message.body.content;
    if (body.length > 64000) throw new Error('Inbox message body exceeds 64,000 characters; it was not truncated or delivered');
    const receivedAt = typeof message?.receivedDateTime === 'string' ? message.receivedDateTime : '';
    if (!receivedAt || Number.isNaN(Date.parse(receivedAt))) throw new Error('Inbox message has an invalid receivedDateTime');
    let sourceUrl = null;
    if (message?.webLink != null && message.webLink !== '') {
      if (typeof message.webLink !== 'string' || !outlookMessageUrl.test(message.webLink)) throw new Error('Inbox message webLink is outside the allowed Outlook hosts');
      sourceUrl = message.webLink;
    }
    const payload = { source: 'secdash-mail', messageId: providerId, sender, subject, body, receivedAt: new Date(receivedAt).toISOString(), category: 'unsorted', supportKind: null, sourceUrl };
    if (Buffer.byteLength(JSON.stringify(payload), 'utf8') > 100000) throw new Error('Inbox message payload exceeds 100 KB; it was not truncated or delivered');
    output.push({ json: payload });
  }
}
return output.length ? output : [{ json: { emptyInbox: true } }];

const results = $input.all();
const mapped = $('Validate and map all messages').all().filter(item => item.json?.emptyInbox !== true);
const sourcePages = $('Read all Inbox pages').all().length;
for (const item of results) {
  if (item.json?.stored !== true || typeof item.json?.id !== 'string' || !/^[a-f0-9]{64}$/i.test(item.json.id)) throw new Error('Dashboard did not confirm a stored message with a valid record ID');
}
if (results.length !== mapped.length) throw new Error('Dashboard delivery count does not match the validated message count');
const recordIds = results.map(item => item.json.id);
if (new Set(recordIds).size !== recordIds.length) throw new Error('Dashboard returned duplicate record IDs for distinct validated messages');
let totalBodyCharacters = 0;
let totalBodyUtf8Bytes = 0;
let oldestReceivedAt = null;
let newestReceivedAt = null;
for (const item of mapped) {
  const body = item.json.body;
  const receivedAt = item.json.receivedAt;
  if (typeof body !== 'string' || typeof receivedAt !== 'string') throw new Error('Validated message metadata is unavailable for the completion proof');
  totalBodyCharacters += body.length;
  totalBodyUtf8Bytes += Buffer.byteLength(body, 'utf8');
  if (oldestReceivedAt === null || receivedAt < oldestReceivedAt) oldestReceivedAt = receivedAt;
  if (newestReceivedAt === null || receivedAt > newestReceivedAt) newestReceivedAt = receivedAt;
}
return [{ json: { completed: true, sourcePages, messageCount: mapped.length, delivered: results.length, recordIds, totalBodyCharacters, totalBodyUtf8Bytes, oldestReceivedAt, newestReceivedAt, category: 'unsorted', mailboxScope: 'Inbox', sourceMessagesChanged: false } }];
